def apply_four_way_mirror():
    """Apply 4-way mirroring from all cells to fill all quadrants"""
    grid = [[9 for _ in range(26)] for _ in range(5)]
    grid[2] = [4] * 26
    for r in range(5):
        grid[r][8] = 4
        grid[r][17] = 4
    grid[3][9:17] = [8, 9, 8, 9, 6, 9, 8, 7]
    grid[4][9:17] = [9, 9, 9, 8, 8, 3, 9, 9]

    wall_row = 2
    wall_col1 = 8
    wall_col2 = 17

    for row in range(5):
        for col in range(26):
            val = grid[row][col]
            if val == 9:
                continue

            # Determine wall-crossed row values (can be row-1, row+1, or row)
            row_vals = [row]
            if wall_row > row:
                row_vals.append(wall_row + (wall_row - row))
            if wall_row < row:
                row_vals.append(wall_row - (row - wall_row))

            # Determine wall-crossed col values
            col_vals = [col]
            for wcol in [wall_col1, wall_col2]:
                if wcol > col:
                    col_vals.append(wcol + (wcol - col))
                elif wcol < col:
                    col_vals.append(wcol - (col - wcol))

                if wcol > col:
                    odd_val = wcol + (wcol - (wcol + (wcol - col)))
                    col_vals.append(odd_val)
                elif wcol < col:
                    odd_val = wcol - ((wcol - (col - wcol)) - wcol)
                    col_vals.append(odd_val)

            for r in row_vals:
                for c in col_vals:
                    if 0 <= r < 5 and 0 <= c < 26:
                        grid[r][c] = val

    return grid

